import { test, expect } from 'vitest';
import crypto from 'node:crypto';

// Reproduction for .stackfold/signature-compatibility.json.
// Uses only the synthetic canonical inputs below plus process.env.STACKFOLD_SIG_SECRET.
// The secret value is never printed, stored, or embedded.
function sign(secret: string, canonical: string): string {
  return crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');
}

function firstDiff(a: string, b: string): number {
  const ab = Buffer.from(a, 'utf8');
  const bb = Buffer.from(b, 'utf8');
  const length = Math.min(ab.length, bb.length);
  for (let i = 0; i < length; i += 1) {
    if (ab[i] !== bb[i]) return i;
  }
  return ab.length === bb.length ? -1 : length;
}

  test("signature mismatch: Raw JSON body", () => {
    const secret = process.env.STACKFOLD_SIG_SECRET;
    if (!secret) throw new Error('Set STACKFOLD_SIG_SECRET to a synthetic test value.');
    const signerCanonical = "POST\n/webhooks/events\na=1\ncontent-type:text/plain\n{\"b\":2,\"a\":1}";
    const verifierCanonical = "POST\n/webhooks/events\na=1\ncontent-type:text/plain\n{\"a\":1,\"b\":2}";
    expect(firstDiff(signerCanonical, verifierCanonical)).toBe(52);
    expect(sign(secret, signerCanonical)).not.toBe(sign(secret, verifierCanonical));
  });

  test("signature mismatch: Query parameter ordering", () => {
    const secret = process.env.STACKFOLD_SIG_SECRET;
    if (!secret) throw new Error('Set STACKFOLD_SIG_SECRET to a synthetic test value.');
    const signerCanonical = "POST\n/webhooks/events\nb=2&a=1\ncontent-type:text/plain\nok";
    const verifierCanonical = "POST\n/webhooks/events\na=1&b=2\ncontent-type:text/plain\nok";
    expect(firstDiff(signerCanonical, verifierCanonical)).toBe(22);
    expect(sign(secret, signerCanonical)).not.toBe(sign(secret, verifierCanonical));
  });

  test("signature mismatch: Unicode normalization", () => {
    const secret = process.env.STACKFOLD_SIG_SECRET;
    if (!secret) throw new Error('Set STACKFOLD_SIG_SECRET to a synthetic test value.');
    const signerCanonical = "POST\n/webhooks/events\na=1\ncontent-type:text/plain\ncafé";
    const verifierCanonical = "POST\n/webhooks/events\na=1\ncontent-type:text/plain\ncafé";
    expect(firstDiff(signerCanonical, verifierCanonical)).toBe(53);
    expect(sign(secret, signerCanonical)).not.toBe(sign(secret, verifierCanonical));
  });

  test("signature mismatch: Timestamp inclusion", () => {
    const secret = process.env.STACKFOLD_SIG_SECRET;
    if (!secret) throw new Error('Set STACKFOLD_SIG_SECRET to a synthetic test value.');
    const signerCanonical = "POST\n/webhooks/events\na=1\ncontent-type:text/plain\nok\n2026-09-24T12:00:00Z";
    const verifierCanonical = "POST\n/webhooks/events\na=1\ncontent-type:text/plain\nok";
    expect(firstDiff(signerCanonical, verifierCanonical)).toBe(52);
    expect(sign(secret, signerCanonical)).not.toBe(sign(secret, verifierCanonical));
  });

  test("signature mismatch: Header name casing", () => {
    const secret = process.env.STACKFOLD_SIG_SECRET;
    if (!secret) throw new Error('Set STACKFOLD_SIG_SECRET to a synthetic test value.');
    const signerCanonical = "POST\n/webhooks/events\na=1\nContent-Type:text/plain\nX-Signature-Version:1\nok";
    const verifierCanonical = "POST\n/webhooks/events\na=1\ncontent-type:text/plain\nx-signature-version:1\nok";
    expect(firstDiff(signerCanonical, verifierCanonical)).toBe(26);
    expect(sign(secret, signerCanonical)).not.toBe(sign(secret, verifierCanonical));
  });

  test("signature mismatch: Percent encoding", () => {
    const secret = process.env.STACKFOLD_SIG_SECRET;
    if (!secret) throw new Error('Set STACKFOLD_SIG_SECRET to a synthetic test value.');
    const signerCanonical = "POST\n/webhooks/events\nlang=en&q=hello%20world\ncontent-type:text/plain\nok";
    const verifierCanonical = "POST\n/webhooks/events\nlang=en&q=hello world\ncontent-type:text/plain\nok";
    expect(firstDiff(signerCanonical, verifierCanonical)).toBe(37);
    expect(sign(secret, signerCanonical)).not.toBe(sign(secret, verifierCanonical));
  });

  test("signature mismatch: Base64-encoded body", () => {
    const secret = process.env.STACKFOLD_SIG_SECRET;
    if (!secret) throw new Error('Set STACKFOLD_SIG_SECRET to a synthetic test value.');
    const signerCanonical = "POST\n/webhooks/events\na=1\ncontent-type:text/plain\naGVsbG8=";
    const verifierCanonical = "POST\n/webhooks/events\na=1\ncontent-type:text/plain\nhello";
    expect(firstDiff(signerCanonical, verifierCanonical)).toBe(50);
    expect(sign(secret, signerCanonical)).not.toBe(sign(secret, verifierCanonical));
  });

  test("signature mismatch: Newline and whitespace", () => {
    const secret = process.env.STACKFOLD_SIG_SECRET;
    if (!secret) throw new Error('Set STACKFOLD_SIG_SECRET to a synthetic test value.');
    const signerCanonical = "POST\n/webhooks/events\na=1\ncontent-type:text/plain\nline1\r\nline2  ";
    const verifierCanonical = "POST\n/webhooks/events\na=1\ncontent-type:text/plain\nline1\nline2";
    expect(firstDiff(signerCanonical, verifierCanonical)).toBe(55);
    expect(sign(secret, signerCanonical)).not.toBe(sign(secret, verifierCanonical));
  });
